#!/usr/bin/env bash
# Regenerates receipt-verification/verifier/SHA256SUMS and receipt-verification/keys/SHA256SUMS.
# Both manifests have cited this script since r1; it first existed at r4 (2026-09-14) — until
# then they were regenerated by hand in this exact format, which is the defect this file closes.
# Scope: each directory only, relative paths, header preserved, entries sorted by path.
# Any commit editing a listed file regenerates its manifest in that same commit.
# Verify with: (cd receipt-verification/verifier && sha256sum -c SHA256SUMS)
set -eu
cd "$(dirname "$0")/.."

regen() {
  local dir="$1"
  (
    cd "$dir"
    header="$(sed -n '1,5p' SHA256SUMS)"
    files="$(find . -type f ! -name SHA256SUMS ! -name 'SHA256SUMS.new' | sed 's#^\./##' | LC_ALL=C sort)"
    { printf '%s\n' "$header"; for f in $files; do sha256sum "$f"; done; } > SHA256SUMS.new
    mv SHA256SUMS.new SHA256SUMS
    sha256sum -c SHA256SUMS > /dev/null && echo "  ok: $dir/SHA256SUMS ($(printf '%s\n' "$files" | wc -l) entries)"
  )
}

regen receipt-verification/verifier
regen receipt-verification/keys
